/// <reference types="vite-plugin-pwa/vanillajs" />
// Service-worker registration (PLAN.md P1-23). The worker itself is generated by vite-plugin-pwa
// (see vite.config.ts); in development `virtual:pwa-register` is a no-op.
import { registerSW } from 'virtual:pwa-register';
import { shouldCheckForUpdate, updates } from './update-store';

export function registerServiceWorker(): void {
  if (!('serviceWorker' in navigator)) return;
  const updateSW = registerSW({
    onNeedRefresh: () => updates.offer(() => updateSW(true)),
    onRegisteredSW: (_url, registration) => {
      if (registration) checkWhenVisible(registration);
    },
    onRegisterError: (error: unknown) => {
      // Offline use is an enhancement; the app keeps working online without a worker.
      console.warn('OpenTiles: the offline service worker could not be registered.', error);
    },
  });
}

/**
 * Browsers look for a new worker on every full page load, but the app uses hash routing and an
 * installed app may never reload. Check again when it comes back to the foreground, at most
 * hourly, and only to our own origin.
 */
function checkWhenVisible(registration: ServiceWorkerRegistration): void {
  let lastCheck = Date.now();
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState !== 'visible') return;
    if (!shouldCheckForUpdate(Date.now(), lastCheck, navigator.onLine)) return;
    lastCheck = Date.now();
    registration.update().catch(() => {
      // Offline or the server is unreachable: try again next time.
    });
  });
}
